Here is an example of the Prim's algorithm implemented in C++:
```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <limits>

using namespace std;

// Structure to represent a graph edge
struct Edge {
    int v1, v2;
};

// Function to find the minimum spanning tree using Prim's algorithm
vector<Edge> primMST(vector<vector<int>>& graph) {
    int V = graph.size();
    vector<bool> visited(V, false);
    vector<int> parent(V, -1); // Parent of each vertex in MST
    vector<Edge> mstEdges; // Minimum Spanning Tree edges

    // Start with an arbitrary vertex (0)
    int s = 0;
    visited[s] = true;

    // Priority queue to select the edge with minimum weight
    priority_queue<pair<int, pair<int, int>>, vector<pair<int, pair<int, int>>>> pq;
    pq.push({0, {s, -1}});

    while (!pq.empty()) {
        int u = pq.top().second.first; // Vertex with minimum weight
        pq.pop();

        for (int v = 0; v < V; ++v) {
            if (graph[u][v] > 0 && !visited[v]) { // Edge exists and not visited
                if (parent[v] == -1 || graph[u][v] < graph[parent[v]][v]) {
                    parent[v] = u;
                    pq.push({graph[u][v], {v, u}});
                }
            }
        }

        visited[u] = true; // Mark vertex as visited
    }

    // Reconstruct the Minimum Spanning Tree edges from parent array
    for (int v = 1; v < V; ++v) {
        mstEdges.push_back({parent[v], v});
    }

    return mstEdges;
}

int main() {
    int numVertices, numEdges;
    cout << "Enter the number of vertices: ";
    cin >> numVertices;

    // Initialize graph as an adjacency matrix
    vector<vector<int>> graph(numVertices);

    for (int i = 0; i < numVertices; ++i) {
        for (int j = 0; j < numVertices; ++j) {
            cout << "Enter weight of edge between vertex " << i << " and " << j << ": ";
            cin >> graph[i][j];
        }
    }

    // Find the Minimum Spanning Tree using Prim's algorithm
    vector<Edge> mstEdges = primMST(graph);

    cout << "\nMinimum Spanning Tree edges: \n";
    for (Edge& e : mstEdges) {
        cout << "(" << e.v1 << ", " << e.v2 << ") ";
    }
    cout << endl;

    return 0;
}
```
This code implements Prim's algorithm to find the Minimum Spanning Tree of a graph represented as an adjacency matrix. The input is taken from the user, and the output shows the edges in the Minimum Spanning Tree.

Note: This code assumes that the input graph is connected and undirected. If your graph has multiple connected components or is directed, you may need to modify the algorithm accordingly.
